cat > solve.py << 'EOF'
import base64

def single_byte_xor(data, key):
    return bytes([b ^ key for b in data])

# Base64 encoded ciphertext
ciphertext = ''

# Decode base64
decoded = base64.b64decode(ciphertext)

# Try each possible byte value
for key in range(256):
    result = single_byte_xor(decoded, key)
    try:
        decoded_text = result.decode('ascii')
        if 'flag{' in decoded_text:
            print(f"Key {key} (0x{key:02x}): {decoded_text}")
    except:
        continue
EOF

python3 solve.py
